(() => {
const views={mix:{title:'Battery electric leads the displayed mix',subtitle:'Share of displayed registrations · percent · saved repository snapshot',source:'assets/ev/plot1.png',rows:[['Battery electric',76.91],['Plug-in hybrid',23.09]],unit:'%',note:'A larger registration share identifies a segment worth investigating; it does not measure charging demand or environmental benefit.'},years:{title:'Model variety across selected model years',subtitle:'Distinct model labels · five model years shown in the original chart · not sales or registration counts',source:'assets/ev/plot4.png',rows:[['2023',70],['2022',60],['2021',44],['2020',39],['2018',35]],unit:' models',note:'These are distinct model labels in a selected snapshot. They do not establish year-on-year sales growth or a complete trend.'}};
const view=document.getElementById('ev-view'),order=document.getElementById('ev-order'),bars=document.getElementById('ev-bars'),observation=document.getElementById('ev-observation');
function render(){const d=views[view.value];document.getElementById('ev-chart-title').textContent=d.title;document.getElementById('ev-chart-subtitle').textContent=d.subtitle;document.getElementById('ev-source').src=d.source;observation.textContent=d.note;let rows=d.rows.map(x=>[...x]);if(order.value!=='source')rows.sort((a,b)=>order.value==='ascending'?a[1]-b[1]:b[1]-a[1]);const max=view.value==='mix'?100:Math.max(...rows.map(r=>r[1]));bars.replaceChildren();rows.forEach(([label,value])=>{const button=document.createElement('button');button.type='button';button.className='ev-bar';const name=document.createElement('span');name.textContent=label;const track=document.createElement('span');track.className='ev-track';const fill=document.createElement('i');fill.style.width=(value/max*100)+'%';track.append(fill);const number=document.createElement('strong');number.textContent=value+d.unit;button.append(name,track,number);button.setAttribute('aria-label',label+': '+value+d.unit);const inspect=()=>{observation.textContent=label+': '+value+d.unit+'. '+d.note;};button.addEventListener('click',inspect);button.addEventListener('focus',inspect);bars.append(button);});}
view.addEventListener('change',render);order.addEventListener('change',render);render();
const stages=[['Load','Airflow loads a local raw CSV into PostgreSQL using pandas to_sql with replace semantics. A second task repeats that ingestion.','Consolidate duplicate tasks; use managed Airflow connections and record source snapshot and ingestion counts.'],['Clean','pandas standardises column names, removes duplicates and drops rows containing missing values. The source is the original CSV, not a database query.','Measure missingness and excluded records, use explicit field rules, and export without an extra index column.'],['Index','Each cleaned row is sent individually to an Elasticsearch index with a positional document identifier.','Use bulk indexing, validate mappings and choose stable source identifiers for repeatable loading.'],['Explore','Saved Kibana figures describe vehicle types, location, models, model years and range. This is the analytical layer after indexing.','Document filters and units; validate denominators and compare insights with an export of the underlying records.']];const group=document.getElementById('ev-stage-buttons');stages.forEach(([name,description,improvement],i)=>{const b=document.createElement('button');b.type='button';b.textContent=(i+1)+' · '+name;b.setAttribute('aria-pressed',String(i===0));b.addEventListener('click',()=>select(i));group.append(b);});function select(i){group.querySelectorAll('button').forEach((b,j)=>b.setAttribute('aria-pressed',String(i===j)));document.getElementById('ev-stage-title').textContent=stages[i][0];document.getElementById('ev-stage-description').textContent=stages[i][1];document.getElementById('ev-stage-improvement').textContent='Next improvement: '+stages[i][2];}select(0);
})();
